#!/usr/bin/env node
// Generates an editor-agnostic .http request collection (VS Code REST Client /
// JetBrains HTTP Client / httpyac) from the OpenAPI contract, grouped by tag,
// plus a multi-environment http-client.env.json (see scripts/lib/http-collection.mjs).
// Regenerated by `task gen`; never edit the output by hand.
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import { parse } from "yaml";
import { generateCollection } from "./lib/http-collection.mjs";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const spec = parse(readFileSync(join(root, "api/openapi.yaml"), "utf8"));
const outDir = join(root, "collections");
mkdirSync(outDir, { recursive: true });

const { files, env } = generateCollection(spec);
for (const [name, content] of files) writeFileSync(join(outDir, name), content);
writeFileSync(join(outDir, "http-client.env.json"), JSON.stringify(env, null, 2) + "\n");

console.log(`Generated ${files.size} .http file(s) + http-client.env.json in collections/`);
